using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
public class CharacterStatisticsEditor:EditorWindow {
 int tab,selected;Vector2 scroll;bool showBaseChances;
 [MenuItem("Editor/Personajes - estadisticas y equipo",false,2001)] public static void Open(){GetWindow<CharacterStatisticsEditor>("Personajes").Show();}
 [InitializeOnLoadMethod] static void Init(){EditorApplication.delayCall+=EnsureCatalog;}
 static void EnsureCatalog(){const string path="Assets/Resources/Combat/EnemyCharacterCatalog.asset";if(AssetDatabase.LoadAssetAtPath<EnemyCharacterCatalog>(path)!=null)return;var source=Resources.Load<EnemyEncounterSettings>("Exploration/EnemyEncounterSettings");var accuracy=Resources.Load<CombatAccuracySettings>("Combat/CombatAccuracySettings");if(source==null)return;var c=CreateInstance<EnemyCharacterCatalog>();string[] names={"TAPAKU","HONGO","SOLDADO","BIG TAPAKU"};int[] hp={source.tapakuHP,source.hongoHP,source.soldierHP,source.bigTapakuHP},damage={source.tapakuDamage,source.hongoDamage,source.soldierDamage,source.bigTapakuDamage};c.enemies=new EnemyCharacterDefinition[4];for(int i=0;i<4;i++)c.enemies[i]=new EnemyCharacterDefinition{character=names[i],category=i==3?EnemyRank.Fuerte:EnemyRank.Enemigo,health=hp[i],strength=damage[i],normalMissPercent=accuracy!=null?accuracy.CharacterMissPercent(names[i],false):10,specialMissPercent=accuracy!=null?accuracy.CharacterMissPercent(names[i],true):25,specialDamage=i==3?source.bigTapakuSpecialDamage:i==2?4:damage[i],specialHits=i==3?source.bigTapakuSpecialHits:1,specialHitInterval=source.bigTapakuSpecialHitInterval};AssetDatabase.CreateAsset(c,path);AssetDatabase.SaveAssets();}
 void OnGUI(){minSize=new Vector2(670,620);EditorGUILayout.LabelField("ESTADÍSTICAS POR PERSONAJE",EditorStyles.boldLabel);int next=GUILayout.Toolbar(tab,new[]{"Personaje","Enemigos","Fuertes","Subjefes","Jefes"});if(next!=tab){tab=next;selected=0;}scroll=EditorGUILayout.BeginScrollView(scroll);
 if(tab==0)DrawPlayer();else DrawEnemies();EditorGUILayout.EndScrollView();if(GUILayout.Button("Guardar estadísticas"))AssetDatabase.SaveAssets();}
 void DrawPlayer(){var player=Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings");var inv=Resources.Load<CombatInventorySettings>("Combat/CombatInventorySettings");var accuracy=Resources.Load<CombatAccuracySettings>("Combat/CombatAccuracySettings");if(player==null||inv==null||accuracy==null)return;EditorGUILayout.LabelField("GAMERBOY",EditorStyles.boldLabel);var inventory=new SerializedObject(inv);inventory.Update();EditorGUILayout.PropertyField(inventory.FindProperty("maximumHP"),new GUIContent("Vida máxima"));inventory.ApplyModifiedProperties();var p=new SerializedObject(player);p.Update();Field(p,"strength","Fuerza / daño normal");Field(p,"defense","Defensa / reducción progresiva");Field(p,"luck","Suerte / puntos porcentuales");EditorGUILayout.HelpBox("La suerte reduce el fallo y aumenta crítico y huida. El equipo suma sus bonos. JUMP no usa suerte ni críticos; la defensa del objetivo sí reduce el daño final.",MessageType.Info);p.ApplyModifiedProperties();DrawPlayerAccuracy(accuracy);p.Update();EditorGUILayout.Space();EditorGUILayout.LabelField("Tres ranuras de equipo inicial",EditorStyles.boldLabel);var slots=p.FindProperty("initialEquipmentIds");slots.arraySize=3;for(int slot=0;slot<3;slot++){var options=new List<string>{"Vacío"};var ids=new List<string>{""};foreach(var e in player.equipment)if(e!=null&&e.SlotIndex==slot){options.Add(e.name);ids.Add(e.id);}var value=slots.GetArrayElementAtIndex(slot);int index=Mathf.Max(0,ids.IndexOf(value.stringValue));int choice=EditorGUILayout.Popup("Ranura "+(slot+1),index,options.ToArray());if(choice!=index)value.stringValue=ids[choice];}p.ApplyModifiedProperties();if(GUILayout.Button("Crear y editar objetos equipables"))EquipmentItemsEditor.Open();}
 void DrawPlayerAccuracy(CombatAccuracySettings accuracy){var player=Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings");var s=new SerializedObject(accuracy);s.Update();var list=s.FindProperty("characters");for(int i=0;i<list.arraySize;i++){var row=list.GetArrayElementAtIndex(i);if(row.FindPropertyRelative("character").stringValue!="GAMERBOY")continue;int luck=player.luck;for(int slot=0;slot<3;slot++)if(player.initialEquipmentIds!=null&&slot<player.initialEquipmentIds.Length)foreach(var item in player.equipment)if(item!=null&&item.SlotIndex==slot&&item.id==player.initialEquipmentIds[slot]){luck+=item.luck;break;}Chances(row.FindPropertyRelative("normalMissPercent").floatValue,row.FindPropertyRelative("specialMissPercent").floatValue,player.criticalPercent,luck,player.fleePercent);showBaseChances=EditorGUILayout.Foldout(showBaseChances,"Ajustar probabilidades base",true);if(showBaseChances){EditorGUILayout.PropertyField(row.FindPropertyRelative("normalMissPercent"),new GUIContent("Fallo normal base (%)"));EditorGUILayout.PropertyField(row.FindPropertyRelative("specialMissPercent"),new GUIContent("Fallo especial base (%)"));var p=new SerializedObject(player);p.Update();Field(p,"criticalPercent","Crítico base (%)");Field(p,"fleePercent","Huida base (%)");p.ApplyModifiedProperties();}}s.ApplyModifiedProperties();var multiplier=new SerializedObject(player);multiplier.Update();Field(multiplier,"criticalMultiplier","Multiplicador de daño crítico");multiplier.ApplyModifiedProperties();}
 static void Chances(float normal,float special,float critical,int luck,float flee=-1){EditorGUILayout.LabelField("Probabilidades finales / suerte total: "+luck,EditorStyles.boldLabel);using(new EditorGUI.DisabledScope(true)){EditorGUILayout.FloatField("Fallo normal (%)",CombatAccuracySettings.EffectiveMiss(normal,luck));EditorGUILayout.FloatField("Fallo especial (%)",CombatAccuracySettings.EffectiveMiss(special,luck));EditorGUILayout.FloatField("Crítico (%)",CombatAccuracySettings.EffectiveBonus(critical,luck));if(flee>=0)EditorGUILayout.FloatField("Huida (%)",CombatAccuracySettings.EffectiveFlee(flee,luck));}EditorGUILayout.HelpBox("La suerte usa coeficientes y límites de Editor > Balance de combate. Crítico y huida tienen topes configurables. GamerBoy incluye los bonos de su equipo inicial; en partida usa el equipo que lleve puesto. JUMP sigue excluido de fallo y crítico aleatorios.",MessageType.None);}

 void DrawEnemies(){var catalog=Resources.Load<EnemyCharacterCatalog>("Combat/EnemyCharacterCatalog");if(catalog==null){EnsureCatalog();return;}var indices=new List<int>();var names=new List<string>();for(int i=0;i<catalog.enemies.Length;i++)if(catalog.enemies[i]!=null&&(int)catalog.enemies[i].category==tab-1){indices.Add(i);names.Add(catalog.enemies[i].character);}if(indices.Count==0)EditorGUILayout.HelpBox("Todavía no hay personajes en esta categoría. Puedes cambiar la categoría de una ficha existente o añadir una ficha para un futuro enemigo.",MessageType.Info);else {selected=Mathf.Clamp(selected,0,indices.Count-1);selected=EditorGUILayout.Popup("Personaje",selected,names.ToArray());var s=new SerializedObject(catalog);s.Update();var entry=s.FindProperty("enemies").GetArrayElementAtIndex(indices[selected]);Property(entry,"character","Nombre visible");Property(entry,"category","Categoría");Property(entry,"health","Vida máxima");Property(entry,"strength","Fuerza / daño normal");Property(entry,"defense","Defensa / reducción progresiva");Property(entry,"luck","Suerte / puntos porcentuales");Chances(entry.FindPropertyRelative("normalMissPercent").floatValue,entry.FindPropertyRelative("specialMissPercent").floatValue,entry.FindPropertyRelative("criticalPercent").floatValue,entry.FindPropertyRelative("luck").intValue);showBaseChances=EditorGUILayout.Foldout(showBaseChances,"Ajustar probabilidades base",true);if(showBaseChances){Property(entry,"normalMissPercent","Fallo normal base (%)");Property(entry,"specialMissPercent","Fallo especial base (%)");Property(entry,"criticalPercent","Crítico base (%)");}Property(entry,"criticalMultiplier","Multiplicador de crítico");EditorGUILayout.Space();EditorGUILayout.LabelField("Ataque especial",EditorStyles.boldLabel);Property(entry,"specialDamage","Daño por golpe");Property(entry,"specialHits","Número de golpes");Property(entry,"specialHitInterval","Pausa entre golpes");s.ApplyModifiedProperties();}
 EditorGUILayout.HelpBox("Los valores se aplican a enemigos nuevos y reaparecidos. La categoría organiza las fichas. Añadir una ficha no crea automáticamente sprites ni habilidades de un enemigo nuevo. Especiales por frames: Big Tapaku, Makuba Lanza y Gran Makuba. Mimic se reserva para cofres y no aparece al azar.",MessageType.None);
 if(GUILayout.Button("Añadir ficha en esta categoría")){Undo.RecordObject(catalog,"Añadir personaje");var list=new List<EnemyCharacterDefinition>(catalog.enemies);list.Add(new EnemyCharacterDefinition{id=System.Guid.NewGuid().ToString("N"),category=(EnemyRank)(tab-1)});catalog.enemies=list.ToArray();EditorUtility.SetDirty(catalog);selected=indices.Count;}}
 static void Field(SerializedObject s,string key,string label,bool children=false){EditorGUILayout.PropertyField(s.FindProperty(key),new GUIContent(label),children);}
 static void Property(SerializedProperty s,string key,string label){EditorGUILayout.PropertyField(s.FindPropertyRelative(key),new GUIContent(label));}
}
